"use client";

import { AlertTriangle, TrendingUp } from "lucide-react";

export default function LeaderboardRuangan({ data }: { data: any[] }) {
  // 1. Hitung total HAIs per ruangan
  const stats = data.reduce((acc: any, curr) => {
    const ruangan = curr.master_ruangan?.nama_ruangan || "Tanpa Nama";
    const totalHais = (curr.isk || 0) + (curr.iad || 0) + (curr.vap || 0) + (curr.hap || 0);
    
    if (!acc[ruangan]) {
      acc[ruangan] = 0;
    }
    acc[ruangan] += totalHais;
    return acc;
  }, {});

  // 2. Ubah ke Array dan urutkan dari yang terbesar
  const sortedStats = Object.entries(stats)
    .map(([name, total]) => ({ name, total }))
    .sort((a: any, b: any) => b.total - a.total)
    .slice(0, 5); // Ambil 5 teratas

  return (
    <div className="bg-white rounded-[2rem] border border-slate-100 p-6 shadow-sm font-sans h-full">
      <div className="flex items-center justify-between mb-6">
        <div>
          <h3 className="text-sm font-black text-slate-800 uppercase italic tracking-tighter">
            Top Ruangan Bermasalah
          </h3>
          <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-1">
            Prioritas Audit HAIs
          </p>
        </div>
        <div className="p-2 bg-red-50 text-red-500 rounded-xl">
          <TrendingUp size={16} />
        </div>
      </div>

      <div className="space-y-4">
        {sortedStats.length === 0 ? (
          <p className="text-[10px] text-slate-400 italic font-bold uppercase py-4 text-center">
            Belum ada temuan kasus HAIs.
          </p>
        ) : (
          sortedStats.map((item: any, idx) => (
            <div key={idx} className="flex items-center gap-4">
              {/* Nomor Urut */}
              <div className="w-6 h-6 rounded-lg bg-slate-50 flex items-center justify-center text-[10px] font-black text-slate-400">
                #{idx + 1}
              </div>
              
              <div className="flex-1">
                <div className="flex justify-between items-end mb-1.5">
                  <span className="text-[11px] font-black text-slate-700 uppercase tracking-tight">
                    {item.name}
                  </span>
                  <span className="text-[10px] font-black text-red-600">
                    {item.total} <small className="opacity-60">KASUS</small>
                  </span>
                </div>
                
                {/* Progress Bar Visual */}
                <div className="w-full h-1.5 bg-slate-50 rounded-full overflow-hidden">
                  <div 
                    className="h-full bg-red-500 rounded-full transition-all duration-1000"
                    style={{ 
                      width: `${(item.total / (sortedStats[0].total || 1)) * 100}%`,
                      opacity: 1 - (idx * 0.15) // Efek gradasi warna
                    }}
                  />
                </div>
              </div>
            </div>
          ))
        )}
      </div>

      {sortedStats.length > 0 && (
        <div className="mt-6 pt-4 border-t border-slate-50">
          <div className="flex items-center gap-2 text-amber-600 bg-amber-50 p-2.5 rounded-xl border border-amber-100">
            <AlertTriangle size={12} className="shrink-0" />
            <p className="text-[9px] font-bold leading-tight uppercase tracking-tight">
              Ruangan {sortedStats[0].name} membutuhkan audit segera.
            </p>
          </div>
        </div>
      )}
    </div>
  );
}